class Solution:
    def frequencySort(self, s: str) -> str:
        from collections import Counter
        counts = Counter(s)
        sorted_chars = sorted(counts.keys(), key=lambda c: -counts[c])
        return ''.join(c * counts[c] for c in sorted_chars)

